 "content": "def transform(grid):
    """Extend the solid rectangle's rows and columns to clear grid edges.

    Sparse non-background cells outside the rectangle block the ray on their
    side; the opposite side is considered independently.
    """
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    color = max(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    # The dominant color is the solid rectangular source object.
    if any(grid[r][c] != color for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        if not any(grid[r][c] != 0 and grid[r][c] != color for c in range(c0)):
            for c in range(c0):
                out[r][c] = color
        if not any(grid[r][c] != 0 and grid[r][c] != color for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = color
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] != 0 and grid[r][c] != color for r in range(r0)):
            for r in range(r0):
                out[r][c] = color
        if not any(grid[r][c] != 0 and grid[r][c] != color for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = color
    return out
